<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nova venda de ingresso</title></head><body style="margin:0;background:#0b0b10;color:#f7f7fb;font-family:Arial,Helvetica,sans-serif"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#0b0b10;padding:28px 12px"><tr><td align="center"><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="max-width:620px;background:#15151d;border:1px solid #2a2a38;border-radius:18px;overflow:hidden"><tr><td style="padding:30px"><div style="font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#a9a9bd;margin-bottom:10px">{{ $applicationName }} · venda confirmada</div><h1 style="font-size:26px;line-height:1.2;margin:0 0 14px;color:#fff">Você vendeu {{ $ticketQuantity }} {{ $ticketQuantity === 1 ? 'ingresso' : 'ingressos' }}</h1><p style="font-size:16px;line-height:1.6;color:#d6d6e2;margin:0 0 24px">Uma nova compra foi aprovada para <strong style="color:#fff">{{ $order->event?->title ?? 'seu evento' }}</strong>.</p><table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background:#0f0f15;border-radius:14px;margin-bottom:24px"><tr><td style="padding:16px 18px;color:#a9a9bd">Pedido</td><td align="right" style="padding:16px 18px;color:#fff;font-weight:bold">#{{ strtoupper(substr((string) $order->public_id, 0, 8)) }}</td></tr><tr><td style="padding:0 18px 16px;color:#a9a9bd">Participante</td><td align="right" style="padding:0 18px 16px;color:#fff">{{ trim(($order->user?->first_name ?? '').' '.($order->user?->last_name ?? '')) ?: ($order->user?->email ?? 'Participante') }}</td></tr><tr><td style="padding:0 18px 16px;color:#a9a9bd">Total</td><td align="right" style="padding:0 18px 16px;color:#fff;font-weight:bold">R$ {{ number_format((float) $order->total, 2, ',', '.') }}</td></tr><tr><td style="padding:0 18px 16px;color:#a9a9bd">Taxa da plataforma</td><td align="right" style="padding:0 18px 16px;color:#fff">R$ {{ number_format((float) $order->platform_fee, 2, ',', '.') }}</td></tr><tr><td style="padding:0 18px 18px;color:#a9a9bd">Líquido da produção</td><td align="right" style="padding:0 18px 18px;color:#79e6b4;font-weight:bold">R$ {{ number_format((float) $order->producer_net, 2, ',', '.') }}</td></tr></table><a href="{{ $saleUrl }}" style="display:inline-block;background:#fff;color:#111118;text-decoration:none;font-weight:bold;padding:13px 20px;border-radius:10px">Ver venda na Cutinapp</a><p style="font-size:12px;line-height:1.5;color:#77778b;margin:24px 0 0">Este aviso é enviado somente após a confirmação do pagamento e emissão válida dos ingressos.</p></td></tr></table></td></tr></table></body></html>
